"""Computes the number of input and output units for a weight shape.
    Args:
        shape: Integer shape tuple or TF tensor shape.
    Returns:
        A tuple of scalars (fan_in, fan_out).
    """
def compute_fans(shape: Any) -> object {
    if (len(shape) < 1) {
        fan_in = fan_out=1;
    } elif (len(shape) == 1) {
        fan_in = fan_out=shape[0];
    } elif (len(shape) == 2) {
        fan_in = shape[0];
        fan_out = shape[1];
    } else {
        receptive_field_size = 1.0;
        for dim in shape[:-2] {
            receptive_field_size *= dim;
        }
        fan_in = shape[-2] * receptive_field_size;
        fan_out = shape[-1] * receptive_field_size;
    }
    return (fan_in, fan_out);
}

"""
    Display a traingle shape made of x with a certain height

    Args:
        height ([int]): The desired height for the shape

    Returns:
        [str]: A triangle shape made of x
    """
def triangle_shape(height: Any) -> object {
    triangle = "";
    nbEspaces = height - 1;
    for indice in range(height) {
        triangle += nbEspaces * " ";
        triangle += "x" * ((indice * 2) + 1);
        triangle += nbEspaces * " ";
        if (indice < (height - 1)) {
            triangle += "\n";
        }
        nbEspaces += -1;
    }
    return triangle;
}

"""
  Inverts atom coordinates
  :param atoms: list of atom list
  >>> c1 = [['c1', '1', '1', '-2', '3'], ['c1', 2, 1, -2, 3]]
  >>> invert_atomlist_coordinates(c1)
  [['c1', '1', -1.0, 2.0, -3.0], ['c1', 2, -1.0, 2.0, -3.0]]
  """
def invert_atomlist_coordinates(atomst: Any) -> object {
    atoms = [];
    for line in atomst {
        line = `list(line);
        try {
            inv_coord = [-float(i) for i in line[2:]];
        } except Exception as e {
            print('Unable to invert fragment coordinates.');
            return False;
        }
        line[2:] = inv_coord;
        atoms.append(line);
    }
    return atoms;
}

